import {STEPS,CONCEPTS,SOURCES} from './steps.js';
import {createJourneyState,transition} from './state.js';
import {DEFAULT_ENERGY,calculateEnergy,fuelEnergy,ENERGY_SOURCES} from './energy.js';
import {PRINCIPLES,PRINCIPLE_SOURCES} from './principles.js';

const $=s=>document.querySelector(s);const fmt=(value,digits=0)=>Number(value).toLocaleString('en-US',{maximumFractionDigits:digits});
let state=createJourneyState(),experience=null,mode='plant',touring=false,tourTimer=null,params={...DEFAULT_ENERGY},energy=calculateEnergy(params),lastPhaseEvent={phase:'running',index:4,name:'持续运行'},loadPowered=true,lightingMode='day',nbiDiagnostic=false,inspectionTimer,autoReveal=true;
const journey=$('#journey'),detail=$('#detail'),content=$('#detail-content');
journey.innerHTML=STEPS.map(step=>`<button class="step-button" data-step="${step.id}" aria-label="第${step.id}步：${step.title}" aria-pressed="false"><span class="step-number">${String(step.id).padStart(2,'0')}</span><span class="step-copy"><strong>${step.shortTitle}</strong><small>${step.english}</small></span><span class="step-state" aria-hidden="true">↗</span></button>`).join('');
journey.addEventListener('click',e=>{const button=e.target.closest('[data-step]');if(button){stopTour();selectStep(Number(button.dataset.step));}});
const legends=[{id:'fuel',label:'燃料 / 回收',color:'#4ca77a',description:'氘氚燃料进入反应区；未反应燃料经分离净化后回到供料系统，燃料仍会被反应消耗。'},{id:'plasma',label:'等离子体',color:'#a078d6',description:'中央托卡马克中的带电粒子群，紫色光环是其位置示意。'},{id:'magnetic',label:'磁场',color:'#4f9fba',description:'磁体和电流形成约束磁场；磁力线用于表达方向，不能约束不带电中子。'},{id:'heat',label:'高温冷却剂',color:'#d7904a',description:'包层吸收能量后，由主冷却回路把热量送到换热设备。'},{id:'steam',label:'蒸汽 / 回水',color:'#6799ad',description:'二回路工质从蒸汽发生器进入汽轮机，冷凝后返回。'},{id:'electricity',label:'电力 / 回供',color:'#b89339',description:'一部分发电输出回供加热、低温和泵，余电才送往负载。流向光点是图示。'}];
$('#legend').innerHTML=legends.map(c=>`<button class="legend-item" title="${c.description}" data-concept="${c.id}"><span class="legend-dot" style="background:${c.color}"></span>${c.label}</button>`).join('');
const legendNote=document.createElement('div');legendNote.className='legend-note';legendNote.hidden=true;legendNote.setAttribute('role','status');$('#legend').append(legendNote);let legendTimer;
$('#legend').addEventListener('click',e=>{const b=e.target.closest('[data-concept]');if(!b)return;legendNote.textContent=legends.find(c=>c.id===b.dataset.concept).description;legendNote.hidden=false;clearTimeout(legendTimer);legendTimer=setTimeout(()=>legendNote.hidden=true,6500);});
const sources=[...new Map([...SOURCES,...ENERGY_SOURCES,...PRINCIPLE_SOURCES].map(s=>[s.url,s])).values()];$('#sources-list').innerHTML=sources.map(s=>`<li><a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.title} ↗</a></li>`).join('');
function updateNavigation(){journey.querySelectorAll('[data-step]').forEach(b=>{const id=Number(b.dataset.step);b.classList.toggle('is-selected',state.selected===id);b.classList.toggle('is-visited',state.visited.includes(id));b.setAttribute('aria-pressed',String(state.selected===id));b.querySelector('.step-state').textContent=state.visited.includes(id)?'✓':'↗';});$('#visit-count').textContent=`${state.visited.length} / ${STEPS.length}`;$('#overview-btn').disabled=state.mode==='overview'&&mode==='plant';$('#stage-mode').textContent=state.mode==='part'?'安装部件 · 近距离观察':state.selected?`${String(state.selected).padStart(2,'0')} / ${STEPS.find(s=>s.id===state.selected).shortTitle}`:mode==='energy'?'能量回流 · 自加热与厂内供电':mode==='exploded'?'整机拆解 · 同心分层结构':'一体化电厂 · 总览';$('#tour-progress').textContent=touring?`顺序导览 ${state.selected} / 9 · 每站 12 秒`:'';}
function principlesHTML(id){return `<section class="science-section" id="science-section" aria-label="关键物理原理"><div class="science-heading"><span>WHY IT WORKS</span><h3>关键原理</h3></div>${(PRINCIPLES[id]||[]).map((card,i)=>`<details class="science-card" ${i===0?'open':''}><summary>${card.title}</summary><div class="science-card-body"><div class="science-formula">${card.formula}</div><p>${card.explanation}</p>${card.stages?`<ol class="beam-stages">${card.stages.map(stage=>`<li>${stage}</li>`).join('')}</ol>`:''}<div class="science-citations">${card.sourceIds.map(sourceId=>{const source=PRINCIPLE_SOURCES.find(s=>s.id===sourceId);return source?`<a href="${source.url}" target="_blank" rel="noopener noreferrer">${source.title} ↗</a>`:'';}).join('')}</div></div></details>`).join('')}</section>`;}
function loadStatusHTML(){return `<div class="load-status ${loadPowered?'is-powered':''}" id="load-status"><i></i><div><strong>${loadPowered?'已供电 · 暖光照明开启':'无净电力送出 · 照明关闭'}</strong><span>店内灯具与路灯跟随当前电力收支</span></div></div><button class="lighting-toggle" id="lighting-toggle" aria-pressed="${lightingMode==='dusk'}">${lightingMode==='dusk'?'☾ 暮色观察 · 切换白天':'☀ 白天观察 · 切换暮色'}</button>`;}
function updateLoadStatus(event){loadPowered=event.powered;const element=$('#load-status');if(element){element.classList.toggle('is-powered',loadPowered);element.querySelector('strong').textContent=loadPowered?'已供电 · 暖光照明开启':'无净电力送出 · 照明关闭';}}
function onLighting(value){lightingMode=value;const button=$('#lighting-toggle');if(button){button.setAttribute('aria-pressed',String(value==='dusk'));button.textContent=value==='dusk'?'☾ 暮色观察 · 切换白天':'☀ 白天观察 · 切换暮色';}}
function onOcclusion(count){const note=$('#visibility-note');note.hidden=count===0;note.textContent=count?'前景已透视 · 当前设备保持实体':'';}
function onInspect(part){const notice=$('#inspection-notice');clearTimeout(inspectionTimer);notice.textContent=`${part.label} · ${matchMedia('(prefers-reduced-motion: reduce)').matches?'金色轮廓提示':'金色高亮两次'}`;notice.hidden=false;inspectionTimer=setTimeout(()=>notice.hidden=true,3400);}
function revealStage(){if(innerWidth<=900)$('#stage').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
function selectStep(id){if(!experience||!STEPS.some(s=>s.id===id))return;if(id!==3)nbiDiagnostic=false;state=transition(state,{type:'select',id});detail.hidden=false;detail.scrollTop=0;document.body.classList.add('detail-open');const step=STEPS.find(s=>s.id===id),parts=experience.getParts(id);content.innerHTML=`<div class="detail-eyebrow">SYSTEM ${String(id).padStart(2,'0')} <span>/ ${String(STEPS.length).padStart(2,'0')}</span></div><h2 class="detail-title">${step.title}</h2>${id===9?loadStatusHTML():id===3?`<div class="beam-demo"><span>可动部件演示</span><div class="beam-key"><i class="ion-negative"></i>负离子 <i class="atom-neutral"></i>中性原子 <i class="ion-positive"></i>残余正离子</div><button id="beam-diagnostic" aria-pressed="${nbiDiagnostic}">${nbiDiagnostic?'诊断截束 · 恢复正常注入':'正常注入 · 试试看诊断截束'}</button><p id="beam-diagnostic-note">${nbiDiagnostic?'量热计合拢，吸收束能；中性束暂不进入等离子体。':'量热计打开让行，中性束沿直线进入等离子体。'}</p></div>`:''}<button class="science-jump" id="science-jump">阅读关键原理 ↓</button><div class="detail-summary">${step.summary.map(t=>`<p>${t}</p>`).join('')}</div><div class="principle"><span>系统如何相连</span><p>${systemNote(id)}</p></div><h3 class="parts-title">已安装部件 <span>选择部件观察实物位置与连接方式</span></h3><div class="parts-list">${parts.map((p,i)=>`<button class="part-button" data-part="${p.id}" aria-pressed="false"><span class="part-index">${i+1}</span><span>${p.label}</span><span>↗</span></button>`).join('')}</div><p class="part-description" id="part-description" aria-live="polite">镜头会优先避开遮挡；前景设备可自动透视，也可单独观察当前部件。</p><button class="reveal-toggle" id="reveal-toggle" aria-pressed="${autoReveal}">◈ 自动透视前景 · ${autoReveal?'开启':'关闭'}</button><button class="back-button" id="isolate-part" aria-pressed="false" disabled>◎ 单独观察部件</button><br><button class="back-button" id="step-reset">↶ 返回此系统全景</button>${[2,3,4,5,6].includes(id)?'<button class="back-button" id="explode-context" style="float:right">展开核心结构 ↗</button>':''}${principlesHTML(id)}<div class="detail-nav"><button class="secondary-button" id="previous-step" ${id===1?'disabled':''}>← 上一系统</button><button class="primary-button" id="next-step">${id===9?'回到全厂 ↗':'下一系统 →'}</button></div>${[5,8].includes(id)?`<div class="cycle-note" data-energy-note>${detailEnergyNote(id)}</div>`:id===7?'<div class="cycle-note">绿色回收管线返回供料系统。燃料回收减少浪费，但反应消耗的燃料仍须补充。</div>':''}`;$('#beam-diagnostic')?.addEventListener('click',()=>{nbiDiagnostic=!nbiDiagnostic;experience.setNbiDiagnostic(nbiDiagnostic);const button=$('#beam-diagnostic');button.setAttribute('aria-pressed',String(nbiDiagnostic));button.textContent=nbiDiagnostic?'诊断截束 · 恢复正常注入':'正常注入 · 试试看诊断截束';$('#beam-diagnostic-note').textContent=nbiDiagnostic?'量热计合拢，吸收束能；中性束暂不进入等离子体。':'量热计打开让行，中性束沿直线进入等离子体。';focusPart('beam-calorimeter');});$('#science-jump').addEventListener('click',()=>$('#science-section').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));$('#lighting-toggle')?.addEventListener('click',()=>{experience.setLighting(lightingMode==='dusk'?'day':'dusk');revealStage();});content.querySelectorAll('[data-part]').forEach(b=>b.addEventListener('click',()=>{stopTour();focusPart(b.dataset.part);}));$('#reveal-toggle').addEventListener('click',()=>{autoReveal=!autoReveal;experience.setAutoReveal(autoReveal);const button=$('#reveal-toggle');button.setAttribute('aria-pressed',String(autoReveal));button.textContent=`◈ 自动透视前景 · ${autoReveal?'开启':'关闭'}`;});$('#isolate-part').addEventListener('click',()=>{const button=$('#isolate-part'),value=button.getAttribute('aria-pressed')!=='true';experience.setIsolated(value);button.setAttribute('aria-pressed',String(value));button.textContent=value?'◎ 恢复周边设备':'◎ 单独观察部件';});$('#step-reset').addEventListener('click',()=>{stopTour();selectStep(id);});$('#previous-step').addEventListener('click',()=>{stopTour();selectStep(id-1);});$('#next-step').addEventListener('click',()=>{stopTour();id===9?overview():selectStep(id+1);});$('#explode-context')?.addEventListener('click',()=>applyMode('exploded'));experience.selectStep(id);updateNavigation();revealStage();}
function systemNote(id){return ({1:'供料装置通过注入管线连接同一台托卡马克，绿色回收支路从燃料处理区返回。',2:'真空室属于中央机组。击穿建立等离子体，真空泵在外围提供受控低压环境。',3:'束源先产生并加速负离子，经中性化与残余离子清除后，中性束沿直线切向注入等离子体；量热计在正常注入时打开让行。',4:'环向线圈、极向线圈和中心螺线管围绕同一个反应区工作，外围低温和控制系统需要持续供能。',5:'α 粒子把部分聚变能留在等离子体中；中子把大部分能量交给包层。两者不应重复计入总能量。',6:'主冷却回路在托卡马克与换热器之间循环，独立二回路把蒸汽送至汽轮机，再经冷凝回水。',7:'抽出的未反应燃料经过分离、净化和同位素处理，经闭合管道回到燃料注入端。',8:'同轴汽轮机驱动发电机，经变压器和开关设备分配电力；其中一部分回供电厂。',9:'配电系统把净输出送到 7‑Eleven 风格便利店。店内约 3000 K 暖光与约 2700 K 路灯的亮灭跟随净电力输出；可切换白天和暮色观察。'})[id];}
function focusPart(id){const part=experience?.getParts(state.selected).find(p=>p.id===id);if(!part)return;state=transition(state,{type:'part',id});experience.focusPart(id);revealStage();content.querySelectorAll('[data-part]').forEach(b=>{b.classList.toggle('is-active',b.dataset.part===id);b.setAttribute('aria-pressed',String(b.dataset.part===id));});$('#part-description').textContent=part.description;$('#isolate-part').disabled=false;$('#isolate-part').setAttribute('aria-pressed','false');$('#isolate-part').textContent='◎ 单独观察部件';updateNavigation();}
function overview(){$('#visibility-note').hidden=true;nbiDiagnostic=false;$('#inspection-notice').hidden=true;state=transition(state,{type:'overview'});detail.hidden=true;document.body.classList.remove('detail-open');experience?.overview();updateNavigation();}
function applyMode(value){$('#visibility-note').hidden=true;nbiDiagnostic=false;$('#inspection-notice').hidden=true;stopTour();mode=value;state=transition(state,{type:'overview'});detail.hidden=true;document.body.classList.remove('detail-open');document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('is-active',b.dataset.mode===value);b.setAttribute('aria-pressed',String(b.dataset.mode===value));});experience?.setMode(value);updateNavigation();}
function stopTour(){clearTimeout(tourTimer);touring=false;$('#tour-btn').textContent='▷ 顺序导览';$('#tour-btn').setAttribute('aria-pressed','false');updateNavigation();}
function tourStep(id){selectStep(id);tourTimer=setTimeout(()=>id<9?tourStep(id+1):(stopTour(),overview()),12000);}
$('#tour-btn').addEventListener('click',()=>{if(touring){stopTour();return;}if(!experience)return;applyMode('plant');touring=true;$('#tour-btn').textContent='■ 结束导览';$('#tour-btn').setAttribute('aria-pressed','true');tourStep(1);});
$('#overview-btn').addEventListener('click',()=>applyMode('plant'));$('#close-detail').addEventListener('click',()=>{stopTour();overview();});document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>applyMode(b.dataset.mode)));$('#reset-btn').addEventListener('click',()=>{stopTour();state.selected?selectStep(state.selected):experience?.overview();});$('#zoom-in').addEventListener('click',()=>experience?.zoom(.82));$('#zoom-out').addEventListener('click',()=>experience?.zoom(1.22));
$('#pause-btn').addEventListener('click',()=>{state=transition(state,{type:'pause',value:!state.paused});experience?.setPaused(state.paused);$('#pause-btn').textContent=state.paused?'▷':'Ⅱ';$('#pause-btn').setAttribute('aria-label',state.paused?'继续动画':'暂停动画');$('#pause-btn').setAttribute('aria-pressed',String(state.paused));});
$('#startup-btn').addEventListener('click',()=>{if(!experience)return;applyMode('energy');if(state.paused)$('#pause-btn').click();experience.startSequence();$('#startup-timeline').hidden=false;$('#startup-btn').textContent='↻ 重新演示启动';});
function netSign(){return Math.abs(energy.netMW)<=1e-8?0:Math.sign(energy.netMW);}
function renderOperation(){const {phase,index,name}=lastPhaseEvent,sign=netSign();$('#operation-title').textContent=name;$('#operation-subtitle').textContent=phase==='startup'?'外部供能 → 反应建立 → 发电回供 · 过程示意':sign>0?'α 自加热 + 厂内电力回供':sign<0?'当前工况需外部电力补充':'收支平衡，暂无净送出';$('#startup-timeline').hidden=phase!=='startup';$('#startup-timeline').querySelectorAll('span').forEach((el,i)=>el.classList.toggle('is-active',i<=index));$('#operation-dot').style.background=phase==='startup'?'#c59943':sign>0?'#36a27a':sign<0?'#be775b':'#81939b';}
function onPhase(event){lastPhaseEvent=event;renderOperation();}
function detailEnergyNote(id){return id===5?`α 粒子提供约 ${fmt(energy.alphaMW)} MWth 自加热，仍是 ${fmt(energy.fusionMW)} MWth 聚变热功率的一部分。`:id===8?`当前稳态教学工况：${fmt(energy.grossMW)} MWe 毛发电 − ${fmt(energy.recirculatingMW)} MWe 厂用电 = ${fmt(energy.netMW)} MWe 净电力${netSign()<0?'（需外部补电）':netSign()===0?'（收支平衡）':''}。`:'';}
function refreshDetailEnergy(){const note=content.querySelector('[data-energy-note]');if(note)note.textContent=detailEnergyNote(state.selected);}
function renderEnergy(){energy=calculateEnergy(params);const sign=netSign();$('#fusion-power').innerHTML=`${fmt(energy.fusionMW)}<small>MWth</small>`;$('#alpha-power').textContent=fmt(energy.alphaMW);$('#gross-power').innerHTML=`${fmt(energy.grossMW)}<small>MWe</small>`;$('#gross-caption').textContent=`(${fmt(energy.fusionMW)} + ${fmt(energy.auxiliaryMW)}) × ${fmt(params.thermalEfficiency*100)}% · 回收热 × 转换率`;$('#internal-power').innerHTML=`${fmt(energy.recirculatingMW)}<small>MWe</small>`;$('#net-power').innerHTML=`${fmt(sign===0?0:energy.netMW)}<small>MWe</small>`;$('#net-state').textContent=sign>0?'净电力送出':sign<0?'需外部电力补充':'收支平衡，暂无净送出';$('#lamp-count').textContent=energy.lamps>=10000?`${fmt(energy.lamps/10000)} 万`:fmt(energy.lamps);$('#loss-power').textContent=fmt(energy.lossesMW);$('#recirc-share').textContent=sign===0?'100% 供厂内使用':Number.isFinite(energy.recirculatingFraction)?`${fmt(energy.recirculatingFraction*100)}% 厂内用电 / 毛发电`:'无毛电力输出';$('#recirc-bar').style.width=`${Math.min(100,energy.recirculatingFraction*100)}%`;$('#net-bar').style.width=`${Math.max(0,100-energy.recirculatingFraction*100)}%`;document.body.classList.toggle('is-negative',sign<0);$('#fusion-input-value').textContent=`${fmt(params.fusionMW)} MWth`;$('#aux-input-value').textContent=`${fmt(params.auxiliaryMW)} MWth`;$('#eff-input-value').textContent=`${fmt(params.thermalEfficiency*100)}%`;experience?.setPower(energy);refreshDetailEnergy();renderOperation();renderFuel();}
function renderFuel(){const grams=Number($('#mass-input').value),f=fuelEnergy(grams,params.thermalEfficiency);$('#mass-value').textContent=grams.toFixed(1);$('#mass-energy').textContent=fmt(f.thermalMWh,1);$('#mass-years').textContent=fmt(f.lampYears);$('.fuel-scale>p').textContent=`假设全部反应、${fmt(params.thermalEfficiency*100)}% 转为毛电能；灯的对比未扣厂用电。`;}
[['fusion-input','fusionMW',1],['aux-input','auxiliaryMW',1],['eff-input','thermalEfficiency',.01]].forEach(([id,key,factor])=>$('#'+id).addEventListener('input',e=>{params[key]=Number(e.target.value)*factor;renderEnergy();}));$('#mass-input').addEventListener('input',renderFuel);renderEnergy();
const dialog=$('#sources-dialog');const showHelp=e=>{e?.preventDefault();dialog.showModal();};$('#help-btn').addEventListener('click',showHelp);$('#sources-link').addEventListener('click',showHelp);$('#close-help').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});document.addEventListener('pointerdown',e=>{const settings=$('#energy-settings');if(settings.open&&!settings.contains(e.target))settings.open=false;});
 document.addEventListener('keydown',e=>{if(dialog.open||e.target.matches('input,textarea,select'))return;if(e.key==='Escape'){stopTour();overview();}if(e.key==='ArrowRight'){e.preventDefault();stopTour();selectStep(Math.min(9,(state.selected||0)+1));}if(e.key==='ArrowLeft'&&state.selected>1){e.preventDefault();stopTour();selectStep(state.selected-1);}if((e.key==='+'||e.key==='=')&&!e.ctrlKey)experience?.zoom(.85);if(e.key==='-'&&!e.ctrlKey)experience?.zoom(1.18);});
updateNavigation();
try{
  const {createExperience}=await import('./scene.js');
  experience=createExperience($('#stage'),{onSelect:id=>{stopTour();selectStep(id);},onPart:id=>{stopTour();focusPart(id);},onReady:()=>$('#status').hidden=true,onPhase,onLoadState:updateLoadStatus,onLighting,onInspect,onOcclusion,onError:message=>{$('#status').hidden=false;$('#status').textContent=message;}});experience.setPower(energy);
}catch(error){console.error(error);$('#status').innerHTML='<strong>电厂场景未能启动</strong><p>请在支持 WebGL 的新版浏览器中开启硬件加速后重试。</p>';}
window.addEventListener('pagehide',()=>{clearTimeout(tourTimer);clearTimeout(inspectionTimer);experience?.dispose();},{once:true});
